{
require_once DOL_DOCUMENT_ROOT.'/custom/chinaplanetoperations/class/OperationsSopService.class.php';
$service=new OperationsSopService($db, (int)$entity);$entity=(int)$entity;$userId=(int)$userId;
$definitions=array(
 'CP-SOP-001'=>array('customer_intake','New customer contact and intake','استقبال وتسجيل عميل جديد','新客户接洽与登记',"Record contact channel and time\nCreate or locate the Dolibarr customer\nLink voice notes, chats and files\nConfirm requirements, budget and deadline\nAssign an owner and next action\nSend customer confirmation","تسجيل قناة ووقت التواصل\nإنشاء العميل أو العثور عليه في دوليبار\nربط التسجيلات الصوتية والمحادثات والملفات\nتأكيد المتطلبات والميزانية والموعد\nتعيين المسؤول والإجراء التالي\nإرسال تأكيد للعميل","记录联系渠道和时间\n在Dolibarr中创建或查找客户\n关联语音、聊天和文件\n确认需求、预算和期限\n分配负责人和下一步行动\n向客户发送确认"),
 'CP-SOP-002'=>array('order_management','New customer order control','ضبط طلب عميل جديد','新客户订单管理',"Verify approved quotation and customer\nRecord products, models, quantities and pictures\nRecord supplier, price and payment terms\nConfirm customer warnings and quality requirements\nSet production milestones and tasks\nPrepare controlled invoice and packing-list data\nArrange QC and shipping","التحقق من العرض المعتمد والعميل\nتسجيل المنتجات والموديلات والكميات والصور\nتسجيل المورد والسعر وشروط الدفع\nتأكيد تحذيرات العميل ومتطلبات الجودة\nتحديد مراحل الإنتاج والمهام\nتجهيز بيانات الفاتورة وقائمة التعبئة\nترتيب الفحص والشحن","核对已批准报价和客户\n记录产品、型号、数量和图片\n记录供应商、价格和付款条件\n确认客户警告和质量要求\n设置生产节点和任务\n准备受控发票和装箱单数据\n安排质检和运输"),
 'CP-SOP-003'=>array('supplier_coordination','Supplier and production follow-up','متابعة المورد والإنتاج','供应商与生产跟进',"Confirm purchase requirements in writing\nObtain proforma invoice and bank details\nVerify payment approval before payment\nConfirm production start and finish dates\nRequest progress evidence\nEscalate delay or specification change\nCollect final packing data","تأكيد متطلبات الشراء كتابيًا\nاستلام الفاتورة الأولية وبيانات البنك\nالتحقق من اعتماد الدفع قبل التحويل\nتأكيد تاريخي بدء وانتهاء الإنتاج\nطلب أدلة تقدم الإنتاج\nتصعيد التأخير أو تغيير المواصفات\nجمع بيانات التعبئة النهائية","书面确认采购要求\n取得形式发票和银行资料\n付款前确认付款批准\n确认生产开始和完成日期\n索取生产进度证据\n延误或规格变化时升级处理\n收集最终包装数据"),
 'CP-SOP-004'=>array('factory_audit','Factory audit: online, onsite or combined','تدقيق المصنع أونلاين أو ميداني أو كلي','工厂线上、现场或综合审核',"Confirm audit mode, scope and price\nCollect license, certificates and factory profile\nComplete online verification\nPrepare onsite checklist when applicable\nConfirm visit appointment and inspector\nInspect capacity, quality system and compliance\nUpload dated photos, videos and files\nPrepare findings, risks and advice\nSupervisor reviews all evidence\nPublish approved report to customer","تأكيد نوع التدقيق والنطاق والسعر\nجمع الرخص والشهادات وملف المصنع\nإكمال التحقق أونلاين\nتجهيز قائمة الزيارة عند الحاجة\nتأكيد الموعد والمفتش\nفحص الطاقة ونظام الجودة والامتثال\nرفع الصور والفيديو والملفات المؤرخة\nإعداد النتائج والمخاطر والنصائح\nمراجعة المشرف لجميع الأدلة\nنشر التقرير المعتمد للعميل","确认审核方式、范围和价格\n收集执照、证书和工厂资料\n完成线上核验\n需要时准备现场检查表\n确认访问时间和审核员\n审核产能、质量体系和合规\n上传带日期的照片、视频和文件\n编写发现、风险和建议\n主管审核全部证据\n向客户发布已批准报告"),
 'CP-SOP-005'=>array('quality_control','Product QC inspection using AQL','استخدام AQL في فحص جودة المنتجات','使用AQL进行产品质量检验',"Review product, model, pictures and approved sample\nRecord customer notes and zero-tolerance warnings\nSelect inspection type and AQL level\nCalculate lot and sample size\nPrepare checklist and measurement tools\nConfirm factory appointment\nPerform quantity, workmanship, function and packing checks\nClassify critical, major and minor defects\nUpload original evidence\nState pass, fail or pending result\nSupervisor approves report before publication","مراجعة المنتج والموديل والصور والعينة المعتمدة\nتسجيل ملاحظات العميل والتحذيرات غير القابلة للتجاوز\nاختيار نوع الفحص ومستوى AQL\nحساب حجم الدفعة والعينة\nتجهيز القائمة وأدوات القياس\nتأكيد موعد المصنع\nفحص الكمية والتصنيع والوظيفة والتعبئة\nتصنيف العيوب الحرجة والرئيسية والثانوية\nرفع الأدلة الأصلية\nتحديد ناجح أو راسب أو معلق\nاعتماد المشرف قبل النشر","审核产品、型号、图片和确认样\n记录客户备注和零容忍警告\n选择检验类型和AQL等级\n计算批量和抽样数量\n准备检查表和测量工具\n确认工厂时间\n检查数量、工艺、功能和包装\n区分致命、严重和轻微缺陷\n上传原始证据\n给出通过、不通过或待定结论\n发布前由主管批准报告"),
 'CP-SOP-006'=>array('shipping_inquiry','Shipping price inquiry','استعلام سعر الشحن','运价询价',"Confirm POL, POD and destination country\nConfirm cargo type, weight, CBM and HS code\nCheck batteries, liquid, powder, oil, chemicals or copy brand\nConfirm Incoterm and container type\nCheck required country services\nRequest comparable quotations\nRecord validity, free time and exclusions\nReview margin and publish approved offer","تأكيد ميناء التحميل والوصول والدولة\nتأكيد نوع ووزن وحجم البضاعة ورمز HS\nفحص البطاريات والسوائل والمساحيق والزيوت والكيماويات والتقليد\nتأكيد الإنكوتيرم ونوع الحاوية\nفحص خدمات الدولة المطلوبة\nطلب عروض قابلة للمقارنة\nتسجيل الصلاحية والوقت المجاني والاستثناءات\nمراجعة الهامش ونشر العرض المعتمد","确认起运港、目的港和国家\n确认货物类型、重量、体积和HS编码\n检查电池、液体、粉末、油品、化学品或仿牌\n确认贸易条款和箱型\n检查目的国所需服务\n索取可比较报价\n记录有效期、免箱期和不含项目\n审核利润并发布批准报价"),
 'CP-SOP-007'=>array('shipping_booking','Shipping booking and forwarder collaboration','حجز الشحن والتعاون مع شركة الشحن','订舱及货代协作',"Create permanent CP-SB reference\nVerify shipper, consignee and notify-party snapshots\nVerify cargo lines, packing, weights, CBM and HS codes\nAttach commercial invoice and packing list\nInternal review then send booking request by company email\nRecord forwarder acceptance or requested changes\nRecord SO and carrier booking numbers separately\nRecord vessel, voyage, cutoffs, ETD and ETA\nReview every document version and approve the current version only\nRecord containers, seals and loading evidence\nReview debit note and payment separately from customer billing\nCreate or update shipment tracking without closing it\nProcess original documents, DHL and country platforms\nClose booking operations while tracking continues","إنشاء مرجع CP-SB دائم\nالتحقق من بيانات الشاحن والمستلم وجهة الإخطار المحفوظة\nالتحقق من بنود البضاعة والتعبئة والأوزان والحجم ورموز HS\nإرفاق الفاتورة وقائمة التعبئة\nمراجعة داخلية ثم إرسال طلب الحجز ببريد الشركة\nتسجيل قبول شركة الشحن أو طلب التعديل\nتسجيل رقم SO ورقم حجز الناقل كلٌ على حدة\nتسجيل السفينة والرحلة ومواعيد القطع والمغادرة والوصول\nمراجعة كل نسخة مستند واعتماد النسخة الحالية فقط\nتسجيل الحاويات والأختام وأدلة التحميل\nمراجعة Debit Note والدفع بعيدًا عن فواتير العميل\nإنشاء أو تحديث تتبع الشحنة دون إغلاقه\nمتابعة الأصول وDHL ومنصات الدول\nإغلاق عملية الحجز مع استمرار التتبع","创建永久CP-SB编号\n核对发货人、收货人和通知方快照\n核对货物明细、包装、重量、体积和HS编码\n附上商业发票和装箱单\n内部审核后用公司邮箱发送订舱申请\n记录货代接受或修改要求\n分别记录SO号和承运人订舱号\n记录船名、航次、截单、ETD和ETA\n审核每个单证版本且只批准当前版本\n记录箱号、封条号和装柜证据\n将Debit Note和付款与客户开票分开审核\n创建或更新货运跟踪且不自动关闭\n处理正本、DHL和目的国平台\n关闭订舱操作但继续跟踪运输"),
 'CP-SOP-008'=>array('export_documents','Commercial invoice and packing list preparation','إعداد الفاتورة التجارية وقائمة التعبئة','商业发票和装箱单制作',"Import supplier file only as source data\nVerify every product name, model and quantity\nNormalize descriptions without inventing data\nAdd pictures, usage and HS code for Chinese customs list\nVerify cartons, units per carton, net weight, gross weight and dimensions\nReconcile totals with the order\nGenerate documents using the approved company template\nSupervisor reviews before issue\nKeep source file and every output revision","استيراد ملف المورد كمصدر بيانات فقط\nالتحقق من اسم وموديل وكمية كل منتج\nتوحيد الوصف دون اختراع بيانات\nإضافة الصور والاستخدام ورمز HS للقائمة الصينية\nالتحقق من الكراتين والوحدات والأوزان والأبعاد\nمطابقة الإجماليات مع الطلب\nتوليد الملفات بقالب الشركة المعتمد\nمراجعة المشرف قبل الإصدار\nحفظ ملف المصدر وكل نسخة ناتجة","供应商文件仅作为源数据导入\n核对每个产品名称、型号和数量\n规范描述但不得编造数据\n为中国报关装箱单添加图片、用途和HS编码\n核对箱数、每箱数量、净重、毛重和尺寸\n总数必须与订单一致\n使用批准的公司模板生成文件\n签发前由主管审核\n保留源文件和每个输出版本"),
 'CP-SOP-009'=>array('loading_warehouse','Warehouse receipt and container loading','استلام المستودع وتحميل الحاوية','仓库收货与装柜',"Issue warehouse receiving plan\nCount and identify supplier packages\nRecord damage or mismatch immediately\nConfirm final packing list before loading\nInspect empty container condition\nRecord container and seal numbers\nTake staged loading photos and videos\nConfirm loaded totals and seal\nUpload evidence and notify operations","إصدار خطة استلام المستودع\nعد وتعريف طرود كل مورد\nتسجيل التلف أو الاختلاف فورًا\nتأكيد قائمة التعبئة النهائية قبل التحميل\nفحص حالة الحاوية الفارغة\nتسجيل رقم الحاوية والختم\nتصوير مراحل التحميل صورًا وفيديو\nتأكيد الإجماليات والختم\nرفع الأدلة وإبلاغ العمليات","发布仓库收货计划\n清点并识别各供应商货物\n立即记录损坏或差异\n装柜前确认最终装箱单\n检查空箱状态\n记录箱号和封条号\n拍摄分阶段装柜照片和视频\n确认装载总数并封箱\n上传证据并通知运营"),
 'CP-SOP-010'=>array('customs','CargoX, Saber and country-platform submission','CargoX وSaber ومنصات الدول','CargoX、Saber及目的国平台提交',"Identify destination-country requirement\nConfirm responsible employee and deadline\nCollect approved source documents only\nValidate importer/exporter and reference numbers\nSubmit without changing approved commercial data\nRecord platform reference and completion time\nUpload proof or screenshot\nPublish customer-safe status only\nEscalate rejection or deadline risk","تحديد متطلبات دولة الوصول\nتعيين المسؤول والموعد\nجمع المستندات المعتمدة فقط\nالتحقق من المستورد والمصدر والأرقام المرجعية\nالتقديم دون تغيير البيانات التجارية المعتمدة\nتسجيل مرجع المنصة ووقت الإكمال\nرفع الإثبات أو صورة الشاشة\nنشر الحالة الآمنة للعميل فقط\nتصعيد الرفض أو خطر التأخير","识别目的国要求\n确认负责人和截止时间\n仅收集已批准源文件\n核对进出口商和参考编号\n不得更改已批准商业数据后提交\n记录平台编号和完成时间\n上传证明或截图\n仅发布客户安全状态\n拒绝或逾期风险时升级"),
 'CP-SOP-011'=>array('customer_communication','Customer communication and email record','التواصل مع العميل وتسجيل البريد','客户沟通与邮件记录',"Use the assigned @chinaplanet.org mailbox\nInclude operation reference in subject\nSend only approved customer-safe content\nRecord decision, promise and deadline\nAttach email or message to the operation\nCreate tasks for every commitment\nNever forward internal cost or supplier-only notes","استخدام بريد @chinaplanet.org المخصص\nإضافة مرجع العملية في الموضوع\nإرسال المحتوى الآمن والمعتمد فقط\nتسجيل القرار والوعد والموعد\nربط البريد أو الرسالة بالعملية\nإنشاء مهمة لكل التزام\nعدم تمرير التكلفة الداخلية أو ملاحظات المورد الخاصة","使用指定的@chinaplanet.org邮箱\n主题中包含业务编号\n只发送已批准且客户可见的内容\n记录决定、承诺和期限\n将邮件或消息关联到业务\n每项承诺建立任务\n不得转发内部成本或供应商专用备注"),
 'CP-SOP-012'=>array('internal_tasks','Daily internal task management','إدارة المهام الداخلية اليومية','内部日常任务管理',"Write one clear deliverable per task\nAssign one responsible owner\nSet priority and realistic deadline\nLink task to its operation when applicable\nMove to waiting only with waiting party and reason\nAttach evidence before review\nReviewer accepts or returns with comment\nMark done only when deliverable is complete\nEscalate overdue urgent work","كتابة مخرج واضح واحد لكل مهمة\nتعيين مسؤول واحد\nتحديد الأولوية وموعد واقعي\nربط المهمة بالعملية عند الحاجة\nالنقل إلى الانتظار مع تحديد الطرف والسبب\nإرفاق الدليل قبل المراجعة\nقبول المراجع أو الإعادة مع تعليق\nتحديد مكتمل بعد اكتمال المخرج فقط\nتصعيد العمل العاجل المتأخر","每个任务写明一个清晰交付物\n分配一名负责人\n设置优先级和合理期限\n适用时关联所属业务\n进入等待状态时注明对象和原因\n审核前附上证据\n审核人接受或注明原因退回\n交付物完成后才能标记完成\n升级逾期紧急工作")
);
$created=0;$skipped=0;
foreach($definitions as $ref=>$d){$res=$db->query("SELECT rowid FROM ".MAIN_DB_PREFIX."cpo_sop WHERE entity=".$entity." AND ref='".$db->escape($ref)."'");if($res&&$db->num_rows($res)){$skipped++;continue;}$catres=$db->query("SELECT rowid FROM ".MAIN_DB_PREFIX."cpo_sop_category WHERE entity=".$entity." AND code='".$db->escape($d[0])."'");$cat=$catres?$db->fetch_object($catres):null;if(!$cat)throw new RuntimeException('Missing category '.$d[0]);$context=array('ref'=>$ref,'fk_category'=>(int)$cat->rowid,'country_code'=>'','pol'=>'','pod'=>'','shipping_line'=>'','service_type'=>'all','container_type'=>'','incoterm'=>'','cargo_type'=>'','document_codes'=>'','effective_date'=>date('Y-m-d'));$base=array('applicability'=>'Use for every matching operation unless a more specific approved SOP applies.','required_information'=>"Customer and operation reference\nResponsible owner\nDeadline\nSource documents and evidence",'required_documents'=>"Approved source documents\nEvidence and communication record",'warnings'=>"Do not invent missing data. Do not expose internal notes, supplier costs or unapproved files.",'escalation_instructions'=>'Escalate safety, compliance, payment, deadline or customer-impact risk to the operations manager.','internal_notes'=>'Controlled operational baseline. Adapt only through a new revision.','responsible_department'=>'Operations','change_summary'=>'Initial controlled release');$tr=array('en_US'=>array_merge($base,array('title'=>$d[1],'procedure_steps'=>$d[4])),'ar_SA'=>array('title'=>$d[2],'applicability'=>'يستخدم لكل عملية مطابقة ما لم يوجد إجراء أكثر تخصيصًا ومعتمدًا.','required_information'=>"مرجع العميل والعملية\nالمسؤول\nالموعد النهائي\nالمستندات والأدلة المصدرية",'procedure_steps'=>$d[5],'required_documents'=>"المستندات المصدرية المعتمدة\nالأدلة وسجل التواصل",'warnings'=>'لا تخترع بيانات ناقصة. لا تكشف الملاحظات الداخلية أو تكلفة المورد أو الملفات غير المعتمدة.','escalation_instructions'=>'تصعيد مخاطر السلامة أو الامتثال أو الدفع أو الموعد أو تأثير العميل إلى مدير العمليات.','internal_notes'=>'خط أساس تشغيلي مضبوط؛ يعدل من خلال مراجعة جديدة فقط.','responsible_department'=>'العمليات','change_summary'=>'الإصدار التشغيلي الأول'),'zh_CN'=>array('title'=>$d[3],'applicability'=>'适用于所有匹配业务，除非存在更具体的已批准SOP。','required_information'=>"客户和业务编号\n负责人\n截止时间\n源文件和证据",'procedure_steps'=>$d[6],'required_documents'=>"已批准源文件\n证据和沟通记录",'warnings'=>'不得编造缺失数据。不得泄露内部备注、供应商成本或未批准文件。','escalation_instructions'=>'安全、合规、付款、期限或客户影响风险必须升级给运营经理。','internal_notes'=>'受控运营基线，只能通过新修订更新。','responsible_department'=>'运营部','change_summary'=>'首次受控发布'));
 $id=$service->create($context,$tr,$userId);$service->publish($id,$userId);$created++;}
return array('created'=>$created,'skipped'=>$skipped);
}
